package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.CmdletInvocationException (generated by CSharpToJava converter). */
public class CmdletInvocationException extends RuntimeException {
    private int hresult;
    public CmdletInvocationException() { super(); }
    public CmdletInvocationException(String message) { super(message); }
    public CmdletInvocationException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
